.header-scroll {
  animation: header-bg linear both;
  animation-timeline: scroll();
  animation-range: 0px 50px;
}

@keyframes header-bg {
  0% {
    background: transparent;
    backdrop-filter: none;
    box-shadow: none;
    border-color: transparent;
    height: calc(var(--spacing) * 20);
  }
  50%,
  100% {
    background: oklch(from var(--background) l c h / 0.8);
    backdrop-filter: blur(24px);
    box-shadow: var(--shadow-lg);
    border-color: oklch(from var(--border) l c h / 0.5);
    height: calc(var(--spacing) * 16);
  }
}

const [isScrolled, setIsScrolled] = useState(false);

useEffect(() => {
  const handler = () => {
    requestAnimationFrame(() => setIsScrolled(window.scrollY > 50));
  };
  window.addEventListener("scroll", handler, { passive: true });
  return () => window.removeEventListener("scroll", handler);
}, []);

// Then in JSX:
<header
  className={`fixed top-0 z-50 ${
    isScrolled
      ? "bg-background/80 backdrop-blur-xl shadow-lg border-border/50"
      : "bg-transparent border-transparent"
  }`}
>
